    uint64_t off = 0;

    // AVX2: process groups of 8 blocks
    if (len >= 8*64){
        __m256i h[8];
        for(int i=0;i<8;i++) h[i] = _mm256_set1_epi32(H[i]);
        while (off + 8*64 <= len){
            sha256_8blocks(data + off, h);
            off += 8*64;
        }
        for(int i=0;i<8;i++) H[i] = _mm256_extract_epi32(h[i], 0);
    }

    // scalar: remaining full blocks
    while (off + 64 <= len){
        sha256_block(data + off, H);
        off += 64;
    }

    // padding
    uint64_t rem = len - off;
    uint64_t total = len + 1 + 8;
    uint64_t padded = ((total + 63) / 64) * 64;
    uint64_t fsize = padded - off;
    uint8_t last[128];
    memcpy(last, data + off, rem);
    last[rem] = 0x80;
    memset(last + rem + 1, 0, fsize - rem - 9);
    for(int i=0;i<8;i++) last[fsize-1-i] = (uint8_t)(bitlen >> (8*i));
    uint64_t nblocks = fsize/64;
    for(uint64_t b=0;b<nblocks;b++) sha256_block(last + b*64, H);

    for(int i=0;i<8;i++){
        uint32_t v = bswap32(H[i]);
        memcpy(out + i*4, &v, 4);
