void sha256_avx2(const uint8_t* data, uint64_t len, uint8_t* out){
    uint32_t H[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                     0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint64_t bitlen = len * 8;
    uint64_t off = 0;

    if (len >= 8*64){
        __m256i h[8];
        for(int i=0;i<8;i++) h[i] = _mm256_set1_epi32(H[i]);
        while (off + 8*64 <= len){
            sha256_8blocks(data + off, h);
            off += 8*64;
        }
        for(int i=0;i<8;i++){
            uint32_t lanes[8];
            _mm256_storeu_si256((__m256i*)lanes, h[i]);
            uint32_t s = 0;
            for(int j=0;j<8;j++) s += lanes[j];
            H[i] = s;
        }
    }

    while (off + 64 <= len){
        sha256_block(data + off, H);
        off += 64;
    }

    uint64_t rem = len - off;
    uint64_t total = len + 1 + 8;
    uint64_t padded = ((total + 63) / 64) * 64;
    uint64_t fsize = padded - off;
    uint8_t last[128];
    memcpy(last, data + off, rem);
    last[rem] = 0x80;
    memset(last + rem + 1, 0, fsize - rem - 9);
    for(int i=0;i<8;i++) last[fsize-1-i] = (uint8_t)(bitlen >> (8*i));
    uint64_t nblocks = fsize/64;
    for(uint64_t b=0;b<nblocks;b++) sha256_block(last + b*64, H);

    for(int i=0;i<8;i++){
        uint32_t v = bswap32(H[i]);
        memcpy(out + i*4, &v, 4);
    }
